from pathlib import Path
import subprocess,json,datetime
R=Path(__file__).resolve().parents[1];jdk=json.loads((R/'.p1-local/jdk.json').read_text(encoding='utf-8-sig'))['javaHome'];p=subprocess.run([str(Path(jdk)/'bin/java.exe'),'-Dfile.encoding=UTF-8','-cp',str(R/'backend/access-service/target/classes'),str(R/'docs/P4CPolicyTest.java')],cwd=R,stdout=subprocess.PIPE,stderr=subprocess.PIPE,encoding='utf-8',errors='replace');report=json.loads(p.stdout) if p.returncode==0 else {'pass':False,'exitCode':p.returncode,'diagnostic':p.stderr};out=R/'docs/p4c-evidence'/('policy-'+datetime.datetime.now().strftime('%Y%m%dT%H%M%S')+'.json');out.write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8');print(json.dumps({'evidence':out.relative_to(R).as_posix(),'pass':report['pass'],'assertions':report.get('assertions',0)}));raise SystemExit(p.returncode)
